$ErrorActionPreference = "Stop"

$root = Get-Location
$frontend = Join-Path $root "frontend"

if (-not (Test-Path (Join-Path $root ".git"))) {
    throw "Run this script from the SakhtYar repository root."
}

if (-not (Test-Path (Join-Path $frontend "package.json"))) {
    throw "frontend\package.json was not found."
}

function Read-Utf8([string]$Path) {
    [System.IO.File]::ReadAllText(
        $Path,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

function Write-Utf8([string]$Path, [string]$Content) {
    $parent = Split-Path $Path -Parent
    if (-not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }

    [System.IO.File]::WriteAllText(
        $Path,
        $Content,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

function Write-Base64File([string]$RelativePath, [string]$Base64) {
    $path = Join-Path $root $RelativePath
    $parent = Split-Path $path -Parent

    if (-not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }

    [System.IO.File]::WriteAllBytes(
        $path,
        [Convert]::FromBase64String($Base64)
    )
}

function Stop-SakhtYarVite5175 {
    $listeners = @(
        Get-NetTCPConnection -LocalPort 5175 -State Listen -ErrorAction SilentlyContinue
    )

    foreach ($listener in $listeners) {
        $pidValue = $listener.OwningProcess
        $proc = Get-CimInstance Win32_Process -Filter "ProcessId = $pidValue" -ErrorAction SilentlyContinue
        $cmd = if ($proc) { [string]$proc.CommandLine } else { "" }

        if (
            ($cmd -match 'vite' -or $cmd -match 'node_modules[\\/]+vite') -and
            ($cmd -match 'SakhtYar' -or $cmd -match 'ChatGPT_Projects')
        ) {
            Write-Host "Stopping stale SakhtYar Vite PID=$pidValue" -ForegroundColor Yellow
            Stop-Process -Id $pidValue -Force
        }
    }

    Start-Sleep -Milliseconds 400
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " SakhtYar UI V5.4 - Login + Account + Users + Animation" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $root ".local\patch-backups\ui-v5.4-$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$filesToBackup = @(
    "frontend\src\pages\LoginPage.tsx",
    "frontend\src\pages\AccountPage.tsx",
    "frontend\src\pages\UsersPage.tsx",
    "frontend\src\pages\CaseDetailPage.tsx",
    "frontend\src\pages\CasesPage.tsx",
    "frontend\src\styles\global.css"
)

Write-Host ""
Write-Host "[1/8] Backup..." -ForegroundColor Cyan

foreach ($relative in $filesToBackup) {
    $source = Join-Path $root $relative

    if (Test-Path $source) {
        $dest = Join-Path $backupRoot $relative
        New-Item -ItemType Directory -Force -Path (Split-Path $dest -Parent) | Out-Null
        Copy-Item $source $dest -Force
    }
}

Write-Host "Backup created: $backupRoot" -ForegroundColor DarkGray

Write-Host ""
Write-Host "[2/8] Redesigning Login and Account pages..." -ForegroundColor Cyan

Write-Base64File "frontend\src\pages\LoginPage.tsx" ""
Write-Base64File "frontend\src\pages\AccountPage.tsx" ""

Write-Host "Login redesigned." -ForegroundColor Green
Write-Host "Account page compacted." -ForegroundColor Green

Write-Host ""
Write-Host "[3/8] Removing duplicate Map tab from CaseDetail..." -ForegroundColor Cyan

Write-Base64File "frontend\src\pages\CaseDetailPage.tsx" ""

Write-Host "Standalone Map tab removed. Map remains inside Property > Location." -ForegroundColor Green

Write-Host ""
Write-Host "[4/8] Adding demo users with different roles..." -ForegroundColor Cyan

Write-Base64File "frontend\src\pages\UsersPage.tsx" ""

Write-Host "Five demo users added to Users UI." -ForegroundColor Green

Write-Host ""
Write-Host "[5/8] Enabling animated status badges on project cards..." -ForegroundColor Cyan

$casesPath = Join-Path $frontend "src\pages\CasesPage.tsx"
$cases = Read-Utf8 $casesPath

$oldTag = '<Tag className="sakhtyar-status-badge" color={status.color}>'
$newTag = '<Tag className={`sakhtyar-status-badge sakhtyar-status-${item.status.toLowerCase()}`} color={status.color}>'

if ($cases.Contains($oldTag)) {
    $cases = $cases.Replace($oldTag, $newTag)
    Write-Utf8 $casesPath $cases
    Write-Host "Animated card status class applied." -ForegroundColor Green
} elseif ($cases.Contains('sakhtyar-status-${item.status.toLowerCase()}')) {
    Write-Host "Animated card status class already present." -ForegroundColor DarkGreen
} else {
    Write-Host "WARNING: CasesPage status tag pattern was not found; continuing." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "[6/8] Installing clean local images..." -ForegroundColor Cyan

$assets = @{}
$assets["frontend/public/assets/sakhtyar/projects/project-01.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-02.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-03.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-04.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-05.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-06.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-07.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-08.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-09.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/projects/project-10.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/heroes/cases-hero.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/heroes/users-hero.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/heroes/account-hero.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/heroes/detail-hero.jpg"] = ""
$assets["frontend/public/assets/sakhtyar/heroes/login-hero.jpg"] = ""

foreach ($relative in $assets.Keys) {
    Write-Base64File $relative $assets[$relative]
}

Write-Host "Clean project / hero / login images installed offline." -ForegroundColor Green

Write-Host ""
Write-Host "[7/8] Applying V5.4 visual and motion polish..." -ForegroundColor Cyan

$cssPath = Join-Path $frontend "src\styles\global.css"
$globalCss = Read-Utf8 $cssPath

$globalCss = [regex]::Replace(
    $globalCss,
    '(?s)/\* === SakhtYar UI V5\.4 START === \*/.*?/\* === SakhtYar UI V5\.4 END === \*/',
    ''
)

$globalCss = $globalCss.TrimEnd() + "`r`n`r`n" + @'
/* === SakhtYar UI V5.4 START === */

@keyframes sakhtyarSoftPulse {
  0%, 100% {
    transform: translateZ(0) scale(1);
    box-shadow: 0 0 0 0 rgba(37, 99, 235, .16);
  }
  50% {
    transform: translateZ(0) scale(1.035);
    box-shadow: 0 0 0 7px rgba(37, 99, 235, 0);
  }
}

@keyframes sakhtyarStatusGreen {
  0%, 100% { box-shadow: 0 0 0 0 rgba(34, 197, 94, .18); }
  50% { box-shadow: 0 0 0 6px rgba(34, 197, 94, 0); }
}

@keyframes sakhtyarStatusAmber {
  0%, 100% { box-shadow: 0 0 0 0 rgba(245, 158, 11, .20); }
  50% { box-shadow: 0 0 0 6px rgba(245, 158, 11, 0); }
}

@keyframes sakhtyarStatusRed {
  0%, 100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, .18); }
  50% { box-shadow: 0 0 0 6px rgba(239, 68, 68, 0); }
}

@keyframes sakhtyarCardIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sakhtyarFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

@keyframes sakhtyarSheen {
  from { transform: translateX(140%) skewX(-18deg); }
  to { transform: translateX(-180%) skewX(-18deg); }
}

.sakhtyar-animated-card {
  animation: sakhtyarCardIn .42s ease both;
}

.sakhtyar-project-card {
  transition:
    transform .22s ease,
    box-shadow .22s ease,
    border-color .22s ease !important;
  animation: sakhtyarCardIn .42s ease both;
}

.sakhtyar-project-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 42px rgba(32, 59, 96, .12) !important;
}

.sakhtyar-project-card:hover .sakhtyar-project-cover img {
  transform: scale(1.025);
}

.sakhtyar-project-cover img {
  transition: transform .45s ease;
}

.sakhtyar-animated-primary {
  position: relative;
  overflow: hidden;
}

.sakhtyar-animated-primary::after {
  content: "";
  position: absolute;
  inset-block: 0;
  width: 42px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255,255,255,.34),
    transparent
  );
  transform: translateX(140%) skewX(-18deg);
}

.sakhtyar-animated-primary:hover::after {
  animation: sakhtyarSheen .65s ease;
}

.sakhtyar-status-chip,
.sakhtyar-status-badge {
  transform-origin: center;
}

.sakhtyar-status-construction,
.sakhtyar-status-active {
  animation: sakhtyarSoftPulse 1.85s ease-in-out infinite;
}

.sakhtyar-status-contract {
  animation: sakhtyarStatusGreen 2.1s ease-in-out infinite;
}

.sakhtyar-status-negotiation,
.sakhtyar-status-pending {
  animation: sakhtyarStatusAmber 2.15s ease-in-out infinite;
}

.sakhtyar-status-on_hold {
  animation: sakhtyarStatusRed 2.3s ease-in-out infinite;
}

.sakhtyar-status-completed {
  box-shadow: 0 0 0 3px rgba(6, 182, 212, .08);
}

