'@

Write-Utf8 $cssPath $globalCss

Write-Host "Animations and compact sizing applied." -ForegroundColor Green

Write-Host ""
Write-Host "[8/8] Clearing cache and building..." -ForegroundColor Cyan

Stop-SakhtYarVite5175

foreach ($path in @(
    (Join-Path $frontend "node_modules\.vite"),
    (Join-Path $frontend "dist")
)) {
    if (Test-Path $path) {
        Remove-Item $path -Recurse -Force
    }
}

Push-Location $frontend
try {
    npm run build

    if ($LASTEXITCODE -ne 0) {
        throw "Frontend build failed."
    }
}
finally {
    Pop-Location
}

git diff --check

if ($LASTEXITCODE -ne 0) {
    throw "git diff --check failed."
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host " DONE - SakhtYar UI V5.4 applied successfully" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Included:" -ForegroundColor Cyan
Write-Host " - Professional Login redesign"
Write-Host " - Compact Account / Security page"
Write-Host " - Duplicate standalone Map tab removed"
Write-Host " - Five role-based demo users shown in Users page"
Write-Host " - Animated status badges for project states"
Write-Host " - Subtle card entrance, hover, icon and button animations"
Write-Host " - Reduced-motion accessibility support"
Write-Host " - Clean local images installed offline"
Write-Host ""
Write-Host "Next:" -ForegroundColor Yellow
Write-Host "  cd D:\ChatGPT_Projects\SakhtYar\source\frontend"
Write-Host "  npm run dev"
Write-Host ""
Write-Host "Then open http://localhost:5175/login and http://localhost:5175/cases"
Write-Host "and press Ctrl+F5."
Write-Host ""
Write-Host "No Docker volume was deleted. No Git commit or push was performed." -ForegroundColor DarkGray
